#include "finite.hpp"
int main(int argc,char**argv){try{ec::check(argc==6||argc==7,"numlines first_abs_cycle stall_start mode out.csv");unsigned n=std::stoul(argv[1]),anchor=std::stoul(argv[2]),start=std::stoul(argv[3]),mode=std::stoul(argv[4]);ec::Bank bank;bank.used=n;for(unsigned i=0;i<n;++i){bank.occupied[i]=i;auto&e=bank.entry[i];e.line=i*64;e.mask=1u<<(i%4);e.value.p[i%4]=0x3f80000040000000ull+i;}std::vector<bool>stim(10000,true);if(argc==7){std::ifstream f(argv[6]);std::string line;std::getline(f,line);while(std::getline(f,line)){auto comma=line.find(',');auto idx=std::stoul(line.substr(0,comma));if(idx<stim.size())stim[idx]=std::stoul(line.substr(comma+1))!=0;}}std::ofstream o(argv[5]);o<<"cycle,event,line,data\n";for(ec::T t=0;t<10000;++t){unsigned cycle=anchor+t;bool ready=argc==7?stim[t]:(mode==0||(cycle-start>150&&cycle%13>=5));unsigned before=bank.enum_index;auto out=ec::enum_clock(bank,t,ready);if(bank.enum_index!=before)o<<t<<",scan,"<<before<<",0\n";if(out)o<<t<<",fragment,"<<out->line<<','<<std::hex<<out->data.p[(out->line/64)%4]<<std::dec<<'\n';if(bank.enum_index==bank.used&&!bank.enum_valid&&bank.enum_raw.empty()&&bank.fragment.empty()){std::cout<<"ENUM_MODEL_PASS "<<n<<" last="<<t<<'\n';return 0;}}throw std::runtime_error("ENUM_WATCHDOG");}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
